ee:message.ee:set-payload:
%dw 2.0
output application/json
var inputText = payload.text default ""
var textLength = sizeOf(inputText)
var positiveWords = ["happy", "joy", "love", "amazing", "great", "wonderful", "fantastic", "excellent", "awesome", "good"]
var negativeWords = ["sad", "angry", "hate", "terrible", "awful", "horrible", "bad", "worst", "disappointed", "upset"]

fun calculateSentiment(text) = do {
    var lowerText = lower(text)
    var positiveCount = positiveWords reduce ((word, acc = 0) -> 
        acc + sizeOf(lowerText splitBy word) - 1
    )
    var negativeCount = negativeWords reduce ((word, acc = 0) -> 
        acc + sizeOf(lowerText splitBy word) - 1
    )
    var score = (positiveCount - negativeCount) / (textLength / 10 + 1)
    ---
    if (score > 0.5) "positive"
    else if (score < -0.5) "negative" 
    else "neutral"
}

fun getVibeIntensity(text) = do {
    var exclamationCount = sizeOf(text splitBy "!") - 1
    var capsCount = sizeOf(text filter ((char) -> char >= "A" and char <= "Z"))
    var intensity = (exclamationCount * 2 + capsCount / textLength * 10)
    ---
    if (intensity > 5) "high"
    else if (intensity > 2) "medium"
    else "low"
}
---
{
    "analysis": {
        "text": inputText,
        "sentiment": calculateSentiment(inputText),
        "vibeIntensity": getVibeIntensity(inputText),
        "wordCount": sizeOf(inputText splitBy " "),
        "characterCount": textLength,
        "timestamp": now(),
        "confidence": if (textLength > 50) "high" else if (textLength > 20) "medium" else "low"
    },
    "recommendations": {
        "musicGenre": if (calculateSentiment(inputText) == "positive") "upbeat" 
                     else if (calculateSentiment(inputText) == "negative") "mellow"
                     else "ambient",
        "mood": calculateSentiment(inputText),
        "suggestedActivity": if (calculateSentiment(inputText) == "positive") "dancing" 
                           else if (calculateSentiment(inputText) == "negative") "relaxation"
                           else "meditation"
    }
}

%dw 2.0
output application/json
var requestedMood = payload.mood default "neutral"
var genre = payload.genre default "mixed"
---
{
    "customPlaylist": {
        "mood": requestedMood,
        "genre": genre,
        "generatedAt": now(),
        "tracks": if (requestedMood == "positive") [
                    "Good Vibes - Dua Lipa",
                    "Sunshine - Matisyahu", 
                    "Walking on Sunshine - Katrina and the Waves"
                  ] else if (requestedMood == "negative") [
                    "Hurt - Johnny Cash",
                    "Black - Pearl Jam",
                    "Mad World - Tears for Fears"
                  ] else [
                    "Breathe Me - Sia",
                    "The Sound of Silence - Simon & Garfunkel",
                    "Hallelujah - Jeff Buckley"
                  ],
        "estimatedDuration": "35 minutes",
        "recommendations": {
            "similar": ["More " ++ requestedMood ++ " vibes", "Curated " ++ genre ++ " selection"],
            "nextSuggestion": if (requestedMood == "positive") "energetic" else "uplifting"
        }
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "message": error.description default "An unexpected error occurred",
        "type": error.errorType.identifier default "UNKNOWN",
        "timestamp": now(),
        "service": "vibes-poc"
    },
    "supportInfo": "Please check your request format and try again"
}
